import sys
import heapq

def main():
    import sys
    import heapq

    def solve(n, edges):
        adj = [[] for _ in range(n)]
        for a, b, c in edges:
            adj[a-1].append((b-1, c))
            adj[b-1].append((a-1, c))

        result = [0] * n
        for x in range(1, n):
            visited = [False] * n
            pq = []
            for i in range(n):
                if len(adj[i]) > x:
                    visited[i] = True
                    for j, c in adj[i]:
                        if not visited[j]:
                            heapq.heappush(pq, (c, i, j))

            while pq and len(pq) > (n - x):
                c, u, v = heapq.heappop(pq)
                if visited[u] and not visited[v]:
                    visited[v] = True
                    result[x] += c
                    for j, c in adj[v]:
                        if not visited[j]:
                            heapq.heappush(pq, c, v, j)

        total_weight = sum(c for _, _, c in edges)
        for x in range(n-1, 0, -1):
            result[x-1] = result[x] + total_weight - sum(result)

        return result

    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    index += 1
    edges = []
    for _ in range(n - 1):
        a = int(input[index])
        b = int(input[index + 1])
        c = int(input[index + 2])
        edges.append((a, b, c))
        index += 3

    result = solve(n, edges)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
